mapper.sql:
WHERE r.tab_type = #{tabType}
  AND r.is_deleted = 0

    AND r.rule_name LIKE CONCAT('%', #{ruleName}, '%')


    AND r.id= #{ruleId}


    AND r.create_by = #{userCode}


    AND LOCATE(#{pageScopeMarker}, COALESCE(r.rule_desc, '')) > 0




            AND r.status = '生效中' AND r.end_date < CURDATE()


            AND r.status = #{status}

                AND r.end_date >= CURDATE()

mapper.update:
UPDATE t_sr_warning_rule
SET is_deleted = 1, update_by = #{updateBy}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT COALESCE(d.key_name, requested.channel) FROM (
SELECT #{code} AS channel
) requested LEFT JOIN t_sr_dim_channel d ON d.status = 1 AND d.is_deleted = 0 AND (d.key_code = requested.channel OR d.key_name = requested.channel)

mapper.sql:
WHERE s.tab_type = #{tabType}
  AND s.is_deleted = 0

    AND s.city_id = #{cityId}

AND s.strategy_id != '999'
AND (s.channel = #{channel} OR s.channel IN (SELECT d.key_code FROM t_sr_dim_channel d WHERE d.key_name = #{channel} AND d.status = 1 AND d.is_deleted = 0 AND (d.tab_type = #{tabType} OR FIND_IN_SET(#{tabType}, d.tab_type) > 0)))
AND s.strategy_class = #{strategyClass}
AND s.county_id = #{countyId}
AND DATE_FORMAT(s.stat_month, '%Y-%m') = #{statMonth}
AND DATE_FORMAT(s.stat_month, '%Y-%m') BETWEEN LEFT(#{rule.dataStartDate}, 7) AND LEFT(#{rule.dataEndDate}, 7)
AND CURDATE() BETWEEN #{rule.startDate} AND #{rule.endDate}

    AND s.channel IN #{item}


    AND s.strategy_id IN #{item}


    AND EXISTS (SELECT 1 FROM t_sr_favorite f WHERE f.strategy_id = s.strategy_id
        AND f.user_id = #{userId} AND f.tab_type = #{tabType} AND f.source IN ('follow', 'manual+follow')
        AND FIND_IN_SET(CAST(#{ruleId} AS CHAR), f.rule_id) > 0 AND f.is_deleted = 0)



    AND EXISTS (SELECT 1 FROM t_sr_strategy_key_audience cg
        WHERE cg.strategy_code = s.strategy_id AND cg.tab_type = 'active'
          AND cg.strategy_class = '重点客群' AND cg.is_deleted = 0
          AND cg.customer_group = #{customerGroup})



    AND s.small_category = #{productName}

mapper.update:
UPDATE t_sr_warning_hit
SET followed = #{followed}, update_time = NOW()
WHERE strategy_id = #{strategyId}
  AND tab_type = #{tabType}
  AND is_deleted = 0
